// ── Field history ────────────────────────────────────────────────────────

QStringList RegistryBackend::fieldHistory(const QString& key) const {
    return QSettings("logos-co", "registry")
               .value("history/" + key, QStringList{}).toStringList();
}

void RegistryBackend::saveHistory(const QString& key, const QString& value) {
    if (value.trimmed().isEmpty()) return;
    QSettings s("logos-co", "registry");
    QStringList h = s.value("history/" + key, QStringList{}).toStringList();
    h.removeAll(value);
    h.prepend(value);
    if (h.size() > 10) h.resize(10);
    s.setValue("history/" + key, h);
}

